	pad := strings.Repeat("x", updateGateManifestMaxBytes+1)
	huge := `{"schema_version":1,"sources":{"seed":{}},"pad":"` + pad + `"}`
	if err := os.WriteFile(filepath.Join(output, "manifest.json"), []byte(huge), 0o600); err != nil {
		t.Fatal(err)
